      "Разогрейте духовку в режиме гриля до среднего нагрева, около 180 °C. Застелите противень фольгой и выложите свиные стейки.",
      "Растопите примерно половину сливочного масла. Смажьте им стейки, посолите и поперчите.",
      "Абрикосы разрежьте пополам и удалите косточки. Разложите их вокруг свинины срезом вверх, смажьте оставшимся маслом, посыпьте хлопьями чили и сахаром мусковадо.",
      "Запекайте на гриле около 15 минут, перевернув свинину в середине приготовления. Мясо должно подрумяниться и полностью приготовиться, а абрикосы — размягчиться, сохранив форму.",
      "Слейте воду с картофеля, оставив немного на дне, удалите лук и лавровый лист, добавьте оставшееся масло и разомните в пюре.",
      "Подавайте свиные стейки с абрикосами и картофельным пюре."
