      "Промойте рис и добавьте к фаршу вместе с водой, вустерширским соусом, солью, копчёной паприкой, чёрным перцем и чесночным порошком.",
      "Тщательно перемешайте фарш. Влажными руками сформируйте шарики одинакового размера.",
      "Разогрейте сковороду с растительным маслом. Обжарьте фрикадельки со всех сторон до золотистой корочки. Для варианта в духовке сначала запеките их на противне при 200 °C до образования корочки.",
