      "Овощи очистите и вымойте. Если используете замороженные кукурузу и спаржу, предварительно разморозьте их.",
      "Разогрейте сковороду с 2–3 столовыми ложками масла. Картофель нарежьте кубиками и обжарьте с двух сторон, затем переложите в глубокую миску.",
      "Лук измельчите, морковь нарежьте. На сковороде с небольшим количеством масла пассеруйте лук, спаржу и морковь до мягкости моркови.",
      "Добавьте овощи к картофелю, всыпьте кукурузу и перемешайте.",
      "На той же сковороде на сильном огне быстро обжарьте свинину до румянца с одной-двух сторон, затем переложите к овощам.",
      "Посолите и приправьте смесь, перемешайте. На дно каждого горшочка положите по лавровому листу и измельчённому зубчику чеснока.",
      "Разложите мясо с овощами по горшочкам, заполняя их примерно на две трети.",
      "Смешайте сметану с томатной пастой и водой. Разлейте заливку по горшочкам, не доливая до краёв.",
