      "Для духовки выложите мясо и бекон в форму, сверху распределите грибы, перец и лук. Добавьте соль и перец, влейте красное вино и воду, накройте фольгой и готовьте при 180 °C около 1,5–2 часов.",
      "Для приготовления на сковороде сначала припустите грибы на сухой сковороде, чтобы вышла влага. Добавьте столовую ложку подсолнечного масла и слегка обжарьте их, затем переложите на тарелку.",
